const PAGE_SIZE=30,typeLabels={human:"인물",character:"애니 캐릭터",animal:"동물"};
const grid=document.querySelector("#galleryGrid"),searchInput=document.querySelector("#searchInput"),filters=document.querySelector("#filters"),loadMore=document.querySelector("#loadMore"),emptyState=document.querySelector("#emptyState"),resultStatus=document.querySelector("#resultStatus");
let items=[],filtered=[],visible=PAGE_SIZE,activeType=new URLSearchParams(location.search).get("type")||"human";
if(!["human","character","animal"].includes(activeType))activeType="human";
const normalized=value=>String(value||"").trim().toLocaleLowerCase("ko-KR");
function fallbackImage(name){const initials=[...name].slice(0,2).join("");return`data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 600"><rect width="480" height="600" fill="#e8eaed"/><circle cx="240" cy="220" r="92" fill="#cdd1d6"/><path d="M70 570c18-128 86-196 170-196s152 68 170 196" fill="#cdd1d6"/><text x="240" y="540" text-anchor="middle" font-family="sans-serif" font-size="40" font-weight="700" fill="#4b5563">${initials}</text></svg>`)}`}
function itemCard(item,index){const article=document.createElement("article");article.className=`dataset-card type-${item.type}`;const media=document.createElement("a");media.className="media";media.href=`/detail?id=${encodeURIComponent(item.id)}`;media.setAttribute("aria-label",`${item.name} 얼굴 분석 상세 보기`);const img=document.createElement("img");img.alt=`${item.name} ${typeLabels[item.type]} 이미지`;img.width=480;img.height=600;img.loading=index<12?"eager":"lazy";img.fetchPriority=index<6?"high":"auto";img.decoding="async";img.referrerPolicy="no-referrer";img.src=item.image||fallbackImage(item.name);img.addEventListener("error",()=>{img.src=fallbackImage(item.name)},{once:true});media.append(img);const body=document.createElement("div");body.className="card-body";const top=document.createElement("div");top.className="card-top";const badge=document.createElement("span");badge.className="type-badge";badge.textContent=typeLabels[item.type];const group=document.createElement("span");group.className="group";group.textContent=item.group||typeLabels[item.type];top.append(badge,group);const title=document.createElement("h3");const titleLink=document.createElement("a");titleLink.href=media.href;titleLink.textContent=item.name;title.append(titleLink);const description=document.createElement("p");description.textContent=item.description||"비교 기준 이미지";body.append(top,title,description);article.append(media,body);return article}
function render(){const shown=filtered.slice(0,visible),fragment=document.createDocumentFragment();shown.forEach((item,index)=>fragment.append(itemCard(item,index)));grid.replaceChildren(fragment);grid.setAttribute("aria-busy","false");emptyState.hidden=filtered.length!==0;loadMore.hidden=shown.length>=filtered.length;resultStatus.textContent=`${typeLabels[activeType]} ${filtered.length.toLocaleString("ko-KR")}개 중 ${shown.length.toLocaleString("ko-KR")}개 표시`}
function applyFilters(){const query=normalized(searchInput.value);filtered=items.filter(item=>item.type===activeType&&(!query||normalized(`${item.name} ${item.group} ${item.description} ${(item.labels||[]).join(" ")}`).includes(query)));visible=PAGE_SIZE;render()}
function renderFilters(counts){filters.replaceChildren(...["human","character","animal"].map(type=>{const button=document.createElement("button");button.type="button";button.textContent=`${typeLabels[type]} ${counts[type]||0}`;button.setAttribute("aria-pressed",String(type===activeType));button.addEventListener("click",()=>{activeType=type;history.replaceState(null,"",`/gallery?type=${type}`);searchInput.value="";filters.querySelectorAll("button").forEach(el=>el.setAttribute("aria-pressed",String(el===button)));applyFilters()});return button}))}
let searchTimer;searchInput.addEventListener("input",()=>{clearTimeout(searchTimer);searchTimer=setTimeout(applyFilters,120)});loadMore.addEventListener("click",()=>{visible+=PAGE_SIZE;render()});
try{const data=await window.lookalikeDatasetLoad();const excluded=await window.lookalikeDatasetState();items=data.items.filter(x=>!excluded.has(x.id));data.count=items.length;data.counts=Object.fromEntries(['human','character','animal'].map(t=>[t,items.filter(x=>x.type===t).length]));document.querySelector("#totalCount").textContent=data.count.toLocaleString("ko-KR");document.querySelector("#humanCount").textContent=data.counts.human.toLocaleString("ko-KR");document.querySelector("#characterCount").textContent=data.counts.character.toLocaleString("ko-KR");document.querySelector("#animalCount").textContent=data.counts.animal.toLocaleString("ko-KR");renderFilters(data.counts);applyFilters()}catch(error){grid.setAttribute("aria-busy","false");resultStatus.textContent="데이터를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.";console.error("Dataset failed to load",error)}
